import React from "react";
import { ColorModeProvider } from "../../lib/styling";
import { FormControl } from "../Form";
import Stack from "../Stack";
import Slider from "./Slider";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Slider> = {
  title: "Components/Slider",
  component: Slider,
};

export default meta;
type Story = StoryObj<typeof Slider>;

export const Basic: Story = {
  tags: ["visual-test"],
  args: {
    defaultValue: [25, 75],
  },
  render: (args) => (
    <div className="w-480">
      <Slider {...args} />
    </div>
  ),
};

export const Dark: Story = {
  tags: ["visual-test"],
  decorators: [withDarkMode],
  render: () => (
    <Stack spacing="2-x" className="w-480">
      <Slider />
      <Slider defaultValue={[25]} />
      <Slider defaultValue={[25, 75]} />
      <Slider defaultValue={[25]} disabled />
    </Stack>
  ),
};

export const Ticks: Story = {
  render: () => (
    <Stack spacing="2-x" className="w-480">
      <Slider ticks={1} />
      <Slider ticks={3} defaultValue={[50]} />
      <Slider ticks={11} step={10} defaultValue={[10, 40]} />
      <Slider ticks={[10, 50, 75]} defaultValue={[20, 45, 85]} />
      <Slider ticks={4} max={9} defaultValue={[6]} />
      <Slider ticks={5} min={10} max={20} step={0.5} defaultValue={[15]} />
    </Stack>
  ),
};

export const MinDistance: Story = {
  render: () => (
    <Stack spacing="2-x" className="w-480">
      <Slider ticks={3} defaultValue={[10, 40]} minDistance={25} />
      <Slider ticks={3} defaultValue={[20, 45, 85]} minDistance={10} />
      <Slider ticks={3} defaultValue={[10, 40]} minDistance={0} />
    </Stack>
  ),
};

export const Labelling: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [value, setValue] = React.useState([0, 1000]);
    return (
      <FormControl label="Price range" required className="w-480">
        <Slider
          max={1000}
          ticks={1}
          step={100}
          value={value}
          ariaLabel={["Min price", "Max price"]}
          getThumbLabel={(index, val) => `$${val}`}
          getTickLabel={(val) => `$${value[0]} to $${value[1]}`}
          onChange={setValue}
          onUpdate={setValue}
        />
      </FormControl>
    );
  },
};

export const Vertical: Story = {
  render: () => (
    <div className="h-360">
      <Slider vertical ticks={5} defaultValue={[25]} />
    </div>
  ),
};

export const Sizes: Story = {
  render: () => (
    <Stack spacing="2-x">
      <Stack spacing="2-x" className="w-480">
        <Slider size="large" />
        <Slider size="large" ticks={5} defaultValue={[25]} />
      </Stack>
      <div className="h-360">
        <Slider vertical size="large" ticks={5} defaultValue={[25]} />
      </div>
    </Stack>
  ),
};
